package com.wizzadrds.theworldremembers.voice; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; class VoiceSchedulerTest{@Test void priorityAndSameNpcRules(){var s=new VoiceScheduler(2);var id=UUID.randomUUID();assertTrue(s.submit(new VoiceJob(id,"a",VoicePriority.DIRECT,1)));assertFalse(s.submit(new VoiceJob(id,"b",VoicePriority.DIRECT,2)));var other=UUID.randomUUID();assertTrue(s.submit(new VoiceJob(other,"danger",VoicePriority.DANGER,3)));assertEquals(2,s.active()+s.queued());}}
